Given n binary strings, the task is to find their sum which is also a binary string.Examples:  Input:  arr[] = ["1101", "111"]Output: "10100"Explanation:Input : arr[] = ["1", "10", "11"]Output : "110" [Approach] Bit-by-bit addition with carryA simple idea is to initialise res = "0" and preform addition of each string with res one by one. The value of res after adding all binary strings is the final answer.For adding res and arr[i], we use the approach used in Add two binary strings.
            C++

    // C++ program to add n binary strings
#include <iostream>
#include <vector>
#include <string>
using namespace std;

// Function to trim leading zeros from a binary string
string trimLeadingZeros(const string &s) {

    // Find the position of the first '1'
    size_t firstOne = s.find('1');
    return (firstOne == string::npos) ? "0" : s.substr(firstOne);
}

// Function adds two binary strings 
string addTwoBinary(string &s1, string &s2) {

    // Trim leading zeros
    s1 = trimLeadingZeros(s1);
    s2 = trimLeadingZeros(s2);

    int n = s1.size();  
    int m = s2.size(); 

    // swap the strings if s1 is of smaller length
    if (n < m) {
        return addTwoBinary(s2, s1);
    }

    int j = m - 1;  
    int carry = 0; 

    // Traverse both strings from the end
    for (int i = n - 1; i >= 0; i--) {

          // Current bit of s1
        int bit1 = s1[i] - '0';  
        int sum = bit1 + carry;

        // If there are remaining bits in s2, add them to the sum
        if (j >= 0) {

              // Current bit of s2
            int bit2 = s2[j] - '0';  
            sum += bit2;
            j--;
        }

        // Calculate the result bit and update carry
        int bit = sum % 2;
        carry = sum / 2;

        // Update the current bit in s1
        s1[i] = (char)(bit + '0');
    }

    // If there's any carry left, update s1
    if (carry > 0) {
        s1 = '1' + s1;
    }

    return s1;
}

// function to add n binary strings
string addBinary(vector<string> &arr) {
    string res = "0";
    for (int i = 0; i < arr.size(); i++)
        res = addTwoBinary(res, arr[i]);
    return res;
}

int main() {
    vector<string> arr = { "1", "10", "11" };
    cout << addBinary(arr);
    return 0;
}


