        // Traverse both strings from the end
        for (int i = n - 1; i >= 0; i--) {

            // Current bit of s1
            int bit1 = s1[i] - '0';
            int sum = bit1 + carry;

            // If there are remaining bits in s2, add them to the sum
            if (j >= 0) {

                // Current bit of s2
                int bit2 = s2[j] - '0';
                sum += bit2;
                j--;
